from abc import ABC, abstractmethod


class PricingStrategy(ABC):
    @abstractmethod
    def apply(self, value: float) -> float:
        pass


class TypeAPricing(PricingStrategy):
    def apply(self, value: float) -> float:
        return value * 1.1


class TypeBPricing(PricingStrategy):
    def apply(self, value: float) -> float:
        return value * 0.9


class TypeCPricing(PricingStrategy):
    def apply(self, value: float) -> float:
        return value * 1.05


class CalculationEngine:
    def __init__(self):
        self._strategies = {
            'A': TypeAPricing(),
            'B': TypeBPricing(),
            'C': TypeCPricing(),
        }

    def calculate_item(self, item: dict) -> float:
        strategy = self._strategies.get(item['type'])
        if not strategy:
            raise ValueError(f"Unknown type: {item['type']}")
        return strategy.apply(item['value'])

    def calculate_total(self, data: list[dict]) -> float:
        return sum(self.calculate_item(item) for item in data)


class CalculatorFacade:
    def __init__(self):
        self._engine = CalculationEngine()

    def calculate(self, data: list[dict]) -> float:
        return self._engine.calculate_total(data)

