class PriceCalculator:
    def __init__(self, rules: list[PricingRule] | None = None):
        self._rules = rules or DEFAULT_RULES

    def _resolve_rule(self, item_type: str) -> PricingRule:
        for rule in self._rules:
            if rule.applies_to(item_type):
                return rule
        raise ValueError(f"Unknown item type: {item_type!r}")

    def calculate(self, items: list[Item]) -> float:
        return sum(self._resolve_rule(item.type).adjust(item.value) for item in items)


# --- Facade ---

class CalculatorFacade:
    """Simplified interface that hides subsystem complexity."""

    def __init__(self, rules: list[PricingRule] | None = None):
        self._calculator = PriceCalculator(rules)

    def calculate(self, data: list[dict]) -> float:
        items = [Item(type=d['type'], value=d['value']) for d in data]
        return self._calculator.calculate(items)

